// Roland SYSTEM-8 PLUG-OUT engines (JUPITER-8, SH-101, JUNO-106, JX-3P, JUNO-60, JUPITER-4, PROMARS, SH-2,
// SYSTEM-100): one editor per engine for the patches of the PLUG-OUT slots 1-3. Each engine's patch is the
// SYSTEM-8's three structs (roland-system8-mem.js): the `patch` struct holds the engine's own values at the same
// offsets with other names, ranges and lists; patch2 (effects, chord memory) and patch3 (step sequencer) are the
// OS's and the same for every engine (roland-system8.js PARAMS).
//
// Sources (roland-system8-plugouts.js, generated by tools/system8/gen_plugouts_js.py): the engine's region 0 image
// (its pages as the unit shows them, its own labels, ranges and value lists, SYNINFO model id) and its Roland
// Cloud plugin script (every value's name, range and default). Values no page shows get the OS catalog texts
// (roland-system8-os.js) and the plugin's name. See docs/devices/roland-system8.md, "PLUG-OUT engine editors".

import { readParam, writeParam } from '../../core/model/memmap.js';
import { unit as unitOf, fromUnit, emptyReport } from '../../core/mainlib/common.js';
import * as M from './roland-system8-mem.js';
import { ENGINES } from './roland-system8-plugouts.js';
import { OS_GROUPS } from './roland-system8-fw.js';
import { osDescribe, osText } from './roland-system8-os.js';
import { SHARED } from './roland-system8.js';
import { saveAction } from './roland-system8-sd.js';
import { tidy } from './translate-helpers.js';

const { S_PATCH, FULL_SIZE, A } = M;
const ONOFF = [[0, 'OFF'], [1, 'ON']];
const range = (a, b) => Array.from({ length: Math.max(0, b - a + 1) }, (_, i) => a + i);
const sgn = (v) => (v > 0 ? `+${v}` : String(v));
const clean = (s) => s.replace(/[()]/g, '').trim();
const keyOf = (s) => clean(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');

// OS catalog rows of the patch struct, by packed offset (offset 0 = OS id 1741 LFO Wave ...)
const OS_PATCH = new Map();
for (const g of Object.values(OS_GROUPS)) if ((g.addr >>> 21) === 3) for (const r of g.rows) OS_PATCH.set(g.addr - A(3) + r[2], r);

const PAT_GROUP = (name) => (/ARP|SCATTER|OCTAVE|KEY HOLD/.test(name) ? 'Arpeggio / keyboard' : /BEND|MOD SENS|CONDITION/.test(name) ? 'Bend / mod' : 'More');
/** The engine's patch-struct parameters: pages from region 0, the rest after them. */
export function engineParams(E) {
  const onPage = new Map();
  E.pages.forEach(([page, ps]) => ps.forEach((q) => { if (!onPage.has(q[0])) onPage.set(q[0], { page, q }); }));
  const used = new Set();
  return E.rows.map(([sname, off, bytes, bits, min, max]) => {
    const os = OS_PATCH.get(off) || null;
    const pg = os ? onPage.get(os[0]) : null;
    let key = keyOf(sname) || `v${off}`;
    while (used.has(key)) key += '_';
    used.add(key);
    const hidden = /^\(/.test(sname) && !pg;
    const p = {
      key, label: (pg && pg.q[1]) || clean(sname), group: pg ? pg.page : hidden ? 'Off the panel' : PAT_GROUP(sname),
      offset: S_PATCH.compact(off), ...(bits === 4 ? { nibbles: bytes } : { size: 1 }), min, max, ...(min < 0 ? { signed: true } : {}),
      section: 'panel', ...(os ? { os: os[0] } : {}),
      help: `Plugin: ${sname}${os ? `; OS catalog: ${os[1].trim()}` : ''}${hidden ? '; the engine shows it on no page' : ''}`,
    };
    // region 0: [OS id, label, min, max, list, display kind (0/2 number, 1 bipolar, 4 list, 5 variation), index]
    const q = pg && pg.q;
    const kindList = q && (q[5] === 4 || q[5] === 5);
    if (q && q[4] > 0 && E.lists[q[4]]) p.options = range(min, max).map((v) => [v, E.lists[q[4]][v - min] ?? String(v)]);
    else if (kindList && min === 0 && max === 1 && !(os && os[9].includes(''))) p.options = ONOFF;
    else if (q && q[5] === 1) p.format = (v) => sgn(v - 128);
    else if (q && q[2] < 0 && q[3] - q[2] === max - min) p.format = (v) => sgn(v - min + q[2]);
    else if (os) {
      const [, , , , omin, omax, , bias, flags, text] = os;
      const b = flags & 2 ? bias : 0;
      const d = omax >= omin ? osDescribe(text, omin, omax) : {};
      if (d.options && max - min <= 255) { const by = new Map(d.options); p.options = range(min, max).map((v) => [v, by.get(v - b) ?? osText(text, v - b, omin)]); }
      else if (d.format) p.format = (v) => d.format(v - b);
      if (max - min > 255 || omax < omin) p.input = 'number';
    } else if (min === 0 && max === 1) p.options = ONOFF;
    if (hidden && !p.options) p.input = 'number';
    return p;
  });
}

/** The engine's default patch: its plugin defaults in the patch struct, the OS defaults in patch2 / patch3. */
export function engineInit(E) {
  const d = SHARED.initPatch();
  d.fill(0, 0, 0x80); d.fill(0, 0x100, 640);
  for (const [, off, bytes, bits, , , def] of E.rows) {
    if (typeof def !== 'number') continue;
    let v = def >>> 0;
    const c = S_PATCH.compact(off);
    for (let i = bytes - 1; i >= 0; i--) { d[c + i] = bits === 4 ? v & 15 : v & 0x7f; v = bits === 4 ? v >>> 4 : v >>> 7; }
  }
  return d;
}

// ------------------------------------------------------------------ translator
const hex = (d) => Array.from(d, (b) => b.toString(16).padStart(2, '0')).join('');
const unhex = (s) => Uint8Array.from(s.match(/../g).map((x) => parseInt(x, 16)));
// shared-model fields at the patch-struct offsets every engine keeps (cutoff 58, resonance 62, ENV 68-74 / 78-84 ...)
const SEM = { cutoff: 58, resonance: 62, fA: 68, fD: 70, fS: 72, fR: 74, aA: 78, aD: 80, aS: 82, aR: 84, lfoRate: 4 };
const nib2 = (d, off) => { const c = S_PATCH.compact(off); return ((d[c] & 15) << 4) | (d[c + 1] & 15); };
const setNib2 = (d, off, v) => { const c = S_PATCH.compact(off); d[c] = (v >> 4) & 15; d[c + 1] = v & 15; };

function makeTranslator(E, family) {
  return {
    toCommon(d) {
      const env = (a, dd, s, r) => ({ attack: unitOf(nib2(d, SEM[a]), 255), decay: unitOf(nib2(d, SEM[dd]), 255), sustain: unitOf(nib2(d, SEM[s]), 255), release: unitOf(nib2(d, SEM[r]), 255) });
      return {
        model: 1, kind: 'patch',
        filter: { type: 'lpf', cutoff: unitOf(nib2(d, SEM.cutoff), 255), resonance: unitOf(nib2(d, SEM.resonance), 255), env: env('fA', 'fD', 'fS', 'fR') },
        amp: { env: env('aA', 'aD', 'aS', 'aR') },
        lfo: [{ rate: unitOf(nib2(d, SEM.lfoRate), 255) }],
        extra: { family, model: E.name, data: hex(d), match: hex(d.slice(0, 0x80)) + hex(d.slice(0x100)) },
      };
    },
    fromCommon(c, base) {
      const report = emptyReport();
      if (c?.extra?.family === family && c.extra.data) { report.mapped.push(`the whole ${E.name} patch`); return { data: unhex(c.extra.data), report }; }
      const d = Uint8Array.from(base);
      const f = c?.filter;
      if (f) {
        if (f.cutoff !== undefined) setNib2(d, SEM.cutoff, fromUnit(f.cutoff, 255));
        if (f.resonance !== undefined) setNib2(d, SEM.resonance, fromUnit(f.resonance, 255));
        if (f.env) { setNib2(d, SEM.fA, fromUnit(f.env.attack, 255)); setNib2(d, SEM.fD, fromUnit(f.env.decay, 255)); setNib2(d, SEM.fS, fromUnit(f.env.sustain, 255)); setNib2(d, SEM.fR, fromUnit(f.env.release, 255)); }
        report.mapped.push('filter');
      }
      const e = c?.amp?.env;
      if (e) { setNib2(d, SEM.aA, fromUnit(e.attack, 255)); setNib2(d, SEM.aD, fromUnit(e.decay, 255)); setNib2(d, SEM.aS, fromUnit(e.sustain, 255)); setNib2(d, SEM.aR, fromUnit(e.release, 255)); report.mapped.push('amp envelope'); }
      if (c?.lfo?.[0]?.rate !== undefined) { setNib2(d, SEM.lfoRate, fromUnit(c.lfo[0].rate, 255)); report.mapped.push('LFO rate'); }
      if (c?.osc?.length) report.dropped.push(`oscillators (the ${E.name} engine's own waves are not mapped from other instruments)`);
      return { data: d, report: tidy(report) };
    },
  };
}

// ------------------------------------------------------------------ the definition
const SLOTS = [[1, 'PLUG-OUT 1'], [2, 'PLUG-OUT 2'], [3, 'PLUG-OUT 3']];

/** Read the slot records (70 00 01 00) and say which slots hold this engine. */
async function findSlots(api, E) {
  const found = [];
  for (const [slot] of SLOTS) {
    const r = await api.g.client.request(Uint8Array.from(M.dt1(M.PLUG.slotInfo, [slot], SHARED.dev(api.ctx))), {
      collect: (_m, raw) => { const p = M.parse(raw); return !!(p?.ok && p.addr === M.PLUG.slotInfo + (1 << 21)); },
      complete: (got) => got.length > 0, timeout: 3000,
    });
    const m = r?.messages?.[0];
    const p = m && M.parse(m.raw ?? m); // the device client keeps {name, sub, raw}
    if (!p) continue;
    const nib = p.data;
    const model = (nib[8] << 12) | (nib[9] << 8) | (nib[10] << 4) | nib[11];
    if (model === E.model) found.push(slot);
  }
  api.toast(found.length ? `${E.name} is in ${found.map((s) => `PLUG-OUT ${s}`).join(', ')}.` : `No slot holds ${E.name}: its patches would play on another engine.`, found.length ? 'info' : 'warn');
  return found;
}

/** The editor definition of PLUG-OUT engine `name` (an ENGINES key). */
export function engineDef(name) {
  const E = ENGINES[name];
  if (!E) throw new Error(`SYSTEM-8: unknown PLUG-OUT ${name}`);
  const family = `roland-system8-${keyOf(name).replace(/_/g, '')}`;
  const own = engineParams(E);
  const shared = SHARED.PARAMS.filter((p) => (p.offset >= 0x80 && p.offset < 0x100) || p.offset >= 640);
  const params = [...own, ...shared];
  const init = () => engineInit(E);
  const TR = makeTranslator(E, family);
  const nameOf = (d) => { let s = ''; for (let i = 0; i < 16; i++) s += String.fromCharCode(((d[0x80 + 2 * i] & 15) << 4) | (d[0x81 + 2 * i] & 15)); return s.replace(/[^\x20-\x7e]/g, ' ').trimEnd(); };
  const setName = (d, text) => { const s = String(text).padEnd(16).slice(0, 16); for (let i = 0; i < 16; i++) { const c = s.charCodeAt(i) >= 32 && s.charCodeAt(i) < 127 ? s.charCodeAt(i) : 32; d[0x80 + 2 * i] = c >> 4; d[0x81 + 2 * i] = c & 15; } };
  const readAt = (api, bases) => M.readFull(api.g.client, bases, SHARED.dev(api.ctx), init());
  const groups = [...new Set(own.map((p) => p.group))];
  const isPlugSlot = (raw) => { const p = SHARED.DATA(raw); const l = p && M.locate(p.addr); return !!l && ((l.kind === 'slot' && l.slot > 0) || l.kind === 'temp'); };
  return {
    coverage: `${E.name} PLUG-OUT (model id ${E.model}) patches in the SYSTEM-8's PLUG-OUT slots 1-3: the engine's own values with its pages, labels and value lists from its region 0 image and the plugin's names for the rest; the OS's effects, chord memory and 64-step sequencer; temporary patch read and live edits, slot read, store and recall; translator.`,
    sysex: { manufacturer: [0x41], model: M.MODEL, deviceIdDefault: M.DEV },
    ports: { input: /SYSTEM-8 CTRL/i, output: /SYSTEM-8 CTRL/i },
    link: SHARED.link,
    linkNeeds: { sysex: 'the USB connection SYSTEM-8 CTRL (choose it as input and output)' },
    minGap: 5,
    recognise: isPlugSlot,
    isOwn: M.isS8,
    isRequest: (raw) => M.parse(raw)?.cmd === 0x11,
    libraryItems: (msgs) => {
      const by = new Map();
      for (const m of msgs) { const p = SHARED.DATA(m); const l = p && M.locate(p.addr); if (!l || !(l.kind === 'slot' && l.slot > 0)) continue; const k = `${l.slot}:${l.patch}`; if (!by.has(k)) by.set(k, { l, msgs: [] }); by.get(k).msgs.push(m); }
      return [...by.entries()].map(([key, { l, msgs: ms }]) => { const r = M.fullFrom(ms, init()); return { key, label: `PLUG-OUT ${l.slot} ${SHARED.slotLabel(0, l.patch)}`, name: r ? nameOf(r.data) : '', object: 'patch', data: r?.data, msgs: ms }; });
    },
    simulate: SHARED.simulate,
    objects: [{
      key: 'patch', page: 'Patch', icon: '♫', label: `${E.name} patch`, size: FULL_SIZE, needs: 'sysex',
      init,
      fetch: (api) => readAt(api, M.tempBases(SHARED.unit.target)),
      target: { label: 'Temporary area', title: 'Which temporary patch the page reads and edits (it must hold a patch of this engine)', options: () => SHARED.TARGETS, value: () => SHARED.unit.target, set: (v) => { SHARED.unit.target = Number(v); } },
      params,
      sections: SHARED.SECTIONS,
      sectionLabel: 'Section',
      sendParam: SHARED.sendParam,
      name: nameOf,
      setName,
      layout: [...groups, 'Delay / chorus', 'Reverb', 'MFX (no menu)', 'Velocity / tempo', 'High resolution', 'Comment', 'Chord memory', 'Step sequencer'].map((group) => ({ group })),
      groupInfo: { 'Off the panel': { table: true, note: 'Values of the patch struct that this engine shows on no page (kept as the plugin and the unit store them).' } },
      cols: 4,
      note: `The ${E.name} engine plays these patches only from a PLUG-OUT slot that holds it ("Find its slot"). Every change goes at once to the temporary patch over SYSTEM-8 CTRL.`,
      actions: [
        { label: 'Find its slot', needs: 'sysex', title: 'Read the PLUG-OUT slot records (70 00 01 00) and say which slots hold this engine', run: (api) => findSlots(api, E) },
        { label: 'Save to SD card...', title: `Write this patch (or a bank of the slot that holds ${E.name}) as a file the SYSTEM-8 can load from its SD card (UTILITY: IMPORT loads one patch at a time into the edit buffer; WRITE on the unit keeps it)`, run: (api) => saveAction(api, { page: 'engine', engine: { model: E.model, version: E.version, name: E.name }, engines: Object.values(ENGINES).map(({ model, version, name: n }) => ({ model, version, name: n })), initSound: init }) },
      ],
      sendAll: { label: 'Send to temporary patch', needs: 'sysex', build: (data, ctx) => M.fullMessages(M.tempBases(SHARED.unit.target), data, SHARED.dev(ctx)) },
      toSyx: (data, ctx) => M.fullMessages(M.tempBases(0), data, SHARED.dev(ctx)),
      fromSyx: (msgs) => M.fullFrom(msgs, init())?.data ?? null,
      toCommon: (d) => TR.toCommon(d),
      fromCommon: (c, base) => TR.fromCommon(c, base),
      slots: {
        label: 'PLUG-OUT slots', banks: SLOTS, count: 64, slotLabel: SHARED.slotLabel,
        namesOnOpen: true, needs: 'sysex', recallNeeds: 'pc', storeNeeds: 'sysex',
        name: nameOf,
        writable: () => true,
        fetch: (api, bank, i) => readAt(api, M.slotBases(bank, i)),
        fetchName: (api, bank, i) => SHARED.readName(api, M.slotPatchAddr(bank, i)),
        recall: (bank, i, ctx) => SHARED.recall(bank)(bank, i, ctx),
        store: (bank, i, ctx, data) => M.fullMessages(M.slotBases(bank, i), data, SHARED.dev(ctx)),
        note: () => `Store only into a slot that holds ${E.name}. ${SHARED.STORE_NOTE}`,
      },
    }],
  };
}

export const ENGINE_IDS = Object.fromEntries(Object.keys(ENGINES).map((n) => [n, `roland-system8-${keyOf(n).replace(/_/g, '')}`]));
export const _test = { engineParams, engineInit, ENGINES, readParam, writeParam };
